                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
                emon.Port.cellsPush(sg, 0);
